cypress_script:
describe('Checkbox Form', () => {
  it('Should check checkbox 1', () => {
    cy.visit('https://the-internet.herokuapp.com/checkboxes');
    cy.get('input[type="checkbox"]').first().check();
    cy.get('input[type="checkbox"]').first().should('be.checked');
  });

  it('Should uncheck checkbox 2', () => {
    cy.visit('https://the-internet.herokuapp.com/checkboxes');
    cy.get('input[type="checkbox"]').last().uncheck();
    cy.get('input[type="checkbox"]').last().should('not.be.checked');
  });
});

playwright_script:
import { test } from '@playwright/test';

test.describe('Checkbox Form', () => {
  test('Should check checkbox 1', async ({ page }) => {
    await page.goto('https://the-internet.herokuapp.com/checkboxes');
    await page.check('input[type="checkbox"]').first();
    const isChecked = await page.isChecked('input[type="checkbox"]').first();
    await expect(isChecked).toBeTruthy();
  });

  test('Should uncheck checkbox 2', async ({ page }) => {
    await page.goto('https://the-internet.herokuapp.com/checkboxes');
    await page.uncheck('input[type="checkbox"]').last();
    const isChecked = await page.isChecked('input[type="checkbox"]').last();
    await expect(isChecked).toBeFalsy();
  });
});
